sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Convert Work Date (start) and End Date strings into ServiceNow GlideDateTime objects for date math
    var startGdt = new GlideDateTime(current.getValue('work_date') + ' 00:00:00');
    var endGdt = new GlideDateTime(current.getValue('end_date') + ' 00:00:00');
    var skipWeekends = (current.getValue('skip_weekends') === '1');

    // Safety check: if End Date is on or before Work Date, do nothing
    if (endGdt.compareTo(startGdt) <= 0) {
        return;
    }

    // Create a moving date pointer starting 1 day AFTER Work Date (since Work Date is already saved as current)
    var iterGdt = new GlideDateTime(startGdt);
    iterGdt.addDaysLocalTime(1);


    // Loop day-by-day until our pointer passes End Date
    while (iterGdt.compareTo(endGdt) <= 0) {
        // getDayOfWeekLocalTime() returns 1=Mon ... 5=Fri, 6=Sat, 7=Sun
        var dayOfWeek = iterGdt.getDayOfWeekLocalTime();
        var isWeekend = (dayOfWeek === 6 || dayOfWeek === 7);

        // Only insert a record if we are NOT skipping weekends, OR today is a weekday
        if (!(skipWeekends && isWeekend)) {
            var newEntry = new GlideRecord('x_783736_time_tr_0_time_entry');
            newEntry.initialize(); // Prepares a blank record with default values
            newEntry.setValue('employee', current.getValue('employee'));
            newEntry.setValue('team', current.getValue('team'));
            newEntry.setValue('project', current.getValue('project'));
            newEntry.setValue('work_date', iterGdt.getDate().getByFormat('yyyy-MM-dd'));
            newEntry.setValue('hours', current.getValue('hours'));
            newEntry.setValue('comment', current.getValue('comment'));
            newEntry.insert(); // Saves the new daily record (and fires Business Rules 2 & 3 automatically!)
        }

        // Move the date pointer forward by 1 day
        iterGdt.addDaysLocalTime(1);
    }

    // Clear End Date on the original record so it cleanly represents just the first day
    var selfGr = new GlideRecord('x_783736_time_tr_0_time_entry');
    if (selfGr.get(current.getUniqueValue())) {
        selfGr.setValue('end_date', '');
        selfGr.setWorkflow(false); // Update silently without re-triggering rules
        selfGr.update();
    }

})(current, previous);
